#!/usr/bin/env python3
"""Terminal Wordle: guess the daily 5-letter word in 6 tries."""
import datetime
import sys
from words import WORDS

MAX_TRIES = 6
GREEN, YELLOW, GREY, RESET, BOLD = "\033[92m", "\033[93m", "\033[90m", "\033[0m", "\033[1m"


def daily_word(words):
    return words[datetime.date.today().toordinal() % len(words)]


def feedback(guess, answer):
    marks = [GREY] * 5
    counts = {}
    for i, ch in enumerate(answer):
        if ch == guess[i]:
            marks[i] = GREEN
        else:
            counts[ch] = counts.get(ch, 0) + 1
    for i, ch in enumerate(guess):
        if marks[i] == GREY and counts.get(ch, 0) > 0:
            marks[i] = YELLOW
            counts[ch] -= 1
    return marks


def render(guess, marks):
    return " ".join(f"{m}{ch.upper()}{RESET}" for ch, m in zip(guess, marks))


def read_guess(valid):
    while True:
        try:
            guess = input(f"{BOLD}Enter guess: {RESET}").strip().lower()
        except EOFError:
            sys.exit("\nBye!")
        if len(guess) != 5 or not guess.isalpha():
            print("Invalid guess: enter exactly 5 letters.")
        elif guess not in valid:
            print("Invalid guess: word not in dictionary.")
        else:
            return guess


def main():
    words = WORDS.split()
    valid = set(words)
    answer = daily_word(words)
    print(f"{BOLD}=== WORDLE ({datetime.date.today()}) ==={RESET}")
    print("Guess the 5-letter word. Green=right spot, Yellow=wrong spot, Grey=not in word.")
    history = []
    for turn in range(1, MAX_TRIES + 1):
        guess = read_guess(valid)
        marks = feedback(guess, answer)
        history.append((guess, marks))
        print()
        for g, m in history:
            print(render(g, m))
        if guess == answer:
            print(f"\n{GREEN}You win! Solved in {turn} {'try' if turn == 1 else 'tries'}.{RESET}")
            return
    print(f"\n{YELLOW}Out of tries. The word was {answer.upper()}.{RESET}")


if __name__ == "__main__":
    try:
        main()
    except KeyboardInterrupt:
        sys.exit("\nBye!")
